{"files":{"probe.test.ts":"import { describe, it, expect } from "vitest";
import { createApp } from "../src/app.ts";
import { memoryDeps } from "../src/deps.ts";
import { sequentialIds } from "../src/ids.ts";
import { login, requirePermission } from "../src/auth/sessions.ts";
import { collaboratorRoutes } from "../src/routes/collaborators.ts";

const deps = memoryDeps();
deps.store = new MemoryStore(deps.events);
deps.ids = sequentialIds();

describe("authz.permission-evaluation", () => {
  it("should enforce per-request permission freshness", async () => {
    const app = createApp(deps);
    app.route("/", collaboratorRoutes);

    // Create users and a repository
    const owner = await login(deps, "owner", "password");
    const collaborator = await login(deps, "collaborator", "password");
    const repo = await app.request("POST", "/repos", {
      headers: { authorization: `Bearer ${owner?.token}` },
      body: JSON.stringify({ name: "repo", visibility: "private" }),
    });
    const repoData = await repo.json();

    // Add collaborator with read access
    await app.request("PUT", `/repos/${repoData.owner}/${repoData.name}/collaborators/collaborator`, {
      headers: { authorization: `Bearer ${owner?.token}` },
      body: JSON.stringify({ role: "read" }),
    });

    // Revoke collaborator's access
    const revokeResponse = await app.request("DELETE", `/repos/${repoData.owner}/${repoData.name}/collaborators/collaborator`, {
      headers: { authorization: `Bearer ${owner?.token}` },
    });
    expect(revokeResponse.status).toBe(204);
    console.log("[probe] OWNER DELETE /repos/owner/repo/collaborators/collaborator -> 204 (expected 204)");

    // Attempt to access the repository as the revoked collaborator
    const accessAttempt = await app.request("GET", `/repos/${repoData.owner}/${repoData.name}`, {
      headers: { authorization: `Bearer ${collaborator?.token}` },
    });

    if (accessAttempt.status === 404 && accessAttempt.headers.get("content-type") === "text/plain") {
      throw new Error("probe not applicable: revoke route is absent");
    }

    expect(accessAttempt.status).toBe(403);
    console.log("[probe] COLLABORATOR GET /repos/owner/repo -> 403 (expected 403)");
  });
});
"},"rationale":"This probe tests the permission evaluation freshness by creating a scenario where a collaborator's access is revoked and then immediately attempting to access the protected resource. It checks that the permission evaluation is per-request, meaning the revoked collaborator should not be able to access the repository after the revocation, ensuring the premise holds. The probe handles different worlds by checking for a 404 response to determine if the revoke route is absent, signaling n/a."}

